import{_ as t,o,c as d,a2 as n}from"./chunks/framework.DGk0zlJw.js";const p=JSON.parse('{"title":"Beacon Componentization Refactor · Current-State Inventory and Target Model Mapping (Phase 0 deliverable)","description":"","frontmatter":{},"headers":[],"relativePath":"design/redesign-2026-10-16-映射与迁移.md","filePath":"design/redesign-2026-10-16-映射与迁移.md"}'),i={name:"design/redesign-2026-10-16-映射与迁移.md"};function c(a,e,r,s,l,h){return o(),d("div",null,[...e[0]||(e[0]=[n('<h1 id="beacon-componentization-refactor-·-current-state-inventory-and-target-model-mapping-phase-0-deliverable" tabindex="-1">Beacon Componentization Refactor · Current-State Inventory and Target Model Mapping (Phase 0 deliverable) <a class="header-anchor" href="#beacon-componentization-refactor-·-current-state-inventory-and-target-model-mapping-phase-0-deliverable" aria-label="Permalink to &quot;Beacon Componentization Refactor · Current-State Inventory and Target Model Mapping (Phase 0 deliverable)&quot;">​</a></h1><p><strong>Basis</strong>: <code>docs/design/redesign-plan-2026-10-16.md</code> (external design draft) + <code>docs/design/redesign-2026-10-16-核验.md</code> (50-item current-state verification, commit <code>759742b</code>) <strong>Inventory time point</strong>: 2026-10-16, based on the code surface at commit <code>759742b</code>. <strong>Nature</strong>: this document is the Phase 0 deliverable of the todo item 「组件化重构分期」 — the current-state inventory, the target-model mapping table, and the gap &amp; migration plan. <strong>Sections 5 and 6 were originally proposals; on 2026-10-16 PATROL1016 decided four items on the user&#39;s behalf and froze the contract — see <code>docs/design/redesign-2026-10-16-契约.md</code> for the decision record and the frozen surface (the HTML boundary item remains an open question).</strong></p><hr><h2 id="_1-current-state-inventory" tabindex="-1">1. Current-state inventory <a class="header-anchor" href="#_1-current-state-inventory" aria-label="Permalink to &quot;1. Current-state inventory&quot;">​</a></h2><h3 id="_1-1-projects-and-file-counts" tabindex="-1">1.1 Projects and file counts <a class="header-anchor" href="#_1-1-projects-and-file-counts" aria-label="Permalink to &quot;1.1 Projects and file counts&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Project</th><th>Files</th><th>Responsibility</th><th>Dependencies</th></tr></thead><tbody><tr><td><code>Beacon.Core</code></td><td>47</td><td>Domain models + abstractions + services (no UI, no Provider dependencies)</td><td>BCL + Logging.Abstractions only (<code>Beacon.Core.csproj:7</code>)</td></tr><tr><td><code>Beacon.App</code></td><td>28</td><td>WinUI 3 shell (the only exe), tray / hotkeys / six windows / composition root</td><td>The four class libraries + WindowsAppSDK</td></tr><tr><td><code>Beacon.Connections</code></td><td>34</td><td>23 kinds of widget Providers + 17 kinds of connection Providers</td><td>Core only</td></tr><tr><td><code>Beacon.Actions</code></td><td>5</td><td>4 generic Action executors</td><td>Core only</td></tr><tr><td><code>Beacon.Storage</code></td><td>6</td><td>JSON config / cache / DPAPI secret store / import-export</td><td>Core + ProtectedData only</td></tr></tbody></table><h3 id="_1-2-widget-providers-23-type-keys" tabindex="-1">1.2 Widget Providers (23 type keys) <a class="header-anchor" href="#_1-2-widget-providers-23-type-keys" aria-label="Permalink to &quot;1.2 Widget Providers (23 type keys)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type key</th><th>Provider</th><th>Connection</th></tr></thead><tbody><tr><td><code>github.pull_requests</code> / <code>github.actions.runs</code></td><td>GitHubPullRequestsProvider / GitHubActionsProvider</td><td>github</td></tr><tr><td><code>http.status</code> / <code>http.quota</code></td><td>HttpStatusProvider / HttpQuotaProvider</td><td>http</td></tr><tr><td><code>jenkins.build</code></td><td>JenkinsBuildProvider</td><td>jenkins</td></tr><tr><td><code>bigmodel.usage</code></td><td>BigModelUsageProvider</td><td>bigmodel</td></tr><tr><td><code>ark.usage</code></td><td>ArkUsageProvider</td><td>ark</td></tr><tr><td><code>claude.usage</code></td><td>ClaudeUsageProvider</td><td>claude</td></tr><tr><td><code>deepseek.balance</code></td><td>DeepSeekBalanceProvider</td><td>deepseek</td></tr><tr><td><code>kimi.coding</code></td><td>KimiCodingUsageProvider</td><td>kimi</td></tr><tr><td><code>moonshot.balance</code></td><td>MoonshotBalanceProvider</td><td>moonshot</td></tr><tr><td><code>mimo.usage</code></td><td>MiMoUsageProvider</td><td>mimo</td></tr><tr><td><code>codex.usage</code></td><td>CodexUsageProvider</td><td>codex</td></tr><tr><td><code>copilot.usage</code></td><td>CopilotUsageProvider</td><td>copilot</td></tr><tr><td><code>opencode.usage</code></td><td>OpenCodeUsageProvider</td><td>opencode</td></tr><tr><td><code>qwen.usage</code></td><td>QwenUsageProvider</td><td>qwen</td></tr><tr><td><code>sensenova.tokenplan</code></td><td>SenseNovaUsageProvider</td><td>sensenova</td></tr><tr><td><code>machine.net</code> / <code>machine.local</code> / <code>machine.git</code></td><td>MachineNetProvider / MachineLocalProvider / GitWorkspaceProvider</td><td>machine (zero credentials)</td></tr><tr><td><code>herald.incidents</code> / <code>herald.feed</code> / <code>herald.deliveries</code></td><td>HeraldIncidentsProvider / HeraldFeedProvider / HeraldDeliveriesProvider</td><td>herald</td></tr></tbody></table><p>Registry: <code>src/Beacon.App/Services/BeaconRuntime.cs:116-141</code>.</p><h3 id="_1-3-connection-providers-17-kinds" tabindex="-1">1.3 Connection Providers (17 kinds) <a class="header-anchor" href="#_1-3-connection-providers-17-kinds" aria-label="Permalink to &quot;1.3 Connection Providers (17 kinds)&quot;">​</a></h3><p><code>github</code> <code>http</code> <code>jenkins</code> <code>bigmodel</code> <code>ark</code> <code>claude</code> <code>deepseek</code> <code>kimi</code> <code>moonshot</code> <code>mimo</code> <code>codex</code> <code>copilot</code> <code>opencode</code> <code>qwen</code> <code>sensenova</code> <code>machine</code> <code>herald</code> (registered from <code>BeaconRuntime.cs:183</code> on).</p><h3 id="_1-4-action-executors-7-type-strings" tabindex="-1">1.4 Action executors (7 Type strings) <a class="header-anchor" href="#_1-4-action-executors-7-type-strings" aria-label="Permalink to &quot;1.4 Action executors (7 Type strings)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Executor</th><th>Source</th></tr></thead><tbody><tr><td><code>open.url</code></td><td>OpenUrlExecutor</td><td><code>src/Beacon.Actions/OpenUrlExecutor.cs:13</code></td></tr><tr><td><code>local.command</code></td><td>LocalCommandExecutor</td><td><code>src/Beacon.Actions/LocalCommandExecutor.cs:11</code></td></tr><tr><td><code>http</code></td><td>HttpExecutor</td><td><code>src/Beacon.Actions/HttpExecutor.cs:12</code></td></tr><tr><td><code>webhook</code></td><td>WebhookExecutor</td><td><code>src/Beacon.Actions/WebhookExecutor.cs:16</code></td></tr><tr><td><code>gh.workflow_dispatch</code></td><td>GitHubWorkflowDispatchExecutor</td><td><code>src/Beacon.Connections/GitHubWorkflowExecutors.cs:70</code></td></tr><tr><td><code>gh.workflow_rerun</code></td><td>GitHubWorkflowRerunExecutor</td><td><code>src/Beacon.Connections/GitHubWorkflowExecutors.cs:98</code></td></tr><tr><td><code>gh.workflow_cancel</code></td><td>GitHubWorkflowCancelExecutor</td><td><code>src/Beacon.Connections/GitHubWorkflowExecutors.cs:121</code></td></tr></tbody></table><h3 id="_1-5-display-surface-windows-all-under-src-beacon-app-windows" tabindex="-1">1.5 Display surface (Windows, all under <code>src/Beacon.App/Windows/</code>) <a class="header-anchor" href="#_1-5-display-surface-windows-all-under-src-beacon-app-windows" aria-label="Permalink to &quot;1.5 Display surface (Windows, all under `src/Beacon.App/Windows/`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Window</th><th>Layer</th><th>Role</th></tr></thead><tbody><tr><td>CapsuleWindow</td><td>L1</td><td>Status capsule (aggregated Severity + counts)</td></tr><tr><td>PinnedHostWindow</td><td>L0</td><td>Desktop pinned host panel (multiple tiles, two-column layout, WM_NCHITTEST pass-through)</td></tr><tr><td>FloatingTileWindow</td><td>L0</td><td>Single-widget floating window (draggable, edge collapse)</td></tr><tr><td>QuickPanelWindow</td><td>L2</td><td>Quick Panel (event board, filtering, RECENT, needs-attention section)</td></tr><tr><td>DetailWindow</td><td>L3</td><td>Single-widget detail + action execution feedback</td></tr><tr><td>SettingsWindow</td><td>—</td><td>Settings (connections / widget wizard / appearance / notification rules)</td></tr></tbody></table><p>The generic row renderer <code>MakeStateRow</code> (<code>QuickPanelWindow.cs:471</code>) is the single construction point for both L2 state rows and event rows — <strong>this is the main replacement surface of the componentization effort</strong>.</p><h3 id="_1-6-beacon-core-service-inventory-24-services-8-abstractions-13-models-events-json" tabindex="-1">1.6 Beacon.Core service inventory (24 services + 8 abstractions + 13 models + events + Json) <a class="header-anchor" href="#_1-6-beacon-core-service-inventory-24-services-8-abstractions-13-models-events-json" aria-label="Permalink to &quot;1.6 Beacon.Core service inventory (24 services + 8 abstractions + 13 models + events + Json)&quot;">​</a></h3><ul><li>Abstractions (8): <code>IActionExecutor</code> <code>ICacheStore</code> <code>IClock</code> <code>IConfigurationStore</code> <code>IConnectionProvider</code> (containing <code>IWidgetProvider</code> / <code>IWidgetProviderResolver</code>) <code>IEventBus</code> (containing <code>IUiDispatcher</code>) <code>INotificationSink</code> <code>ISecretStore</code></li><li>Models (13): <code>ActionModels</code> <code>AppConfig</code> <code>ConnectionConfig</code> <code>ConnectionHealthState</code> <code>LifecycleState</code> <code>NotificationModels</code> <code>PinLayout</code> <code>RefreshTiers</code> <code>Severity</code> <code>WidgetConfig</code> <code>WidgetDisplayPolicy</code> <code>WidgetState</code> <code>WidgetTypeDescriptor</code></li><li>Services (24): <code>ActionRunner</code> <code>ActionVisibility</code> <code>BrandIcons</code> <code>ContrastMath</code> <code>DebugInjection</code> <code>DispatchGuard</code> <code>DpiLayoutMath</code> <code>EventBus</code> <code>HighContrastPalette</code> <code>NotificationEngine</code> <code>PaletteResolver</code> <code>PinLayoutMath</code> <code>QuickPanelFilter</code> <code>QuickPanelSections</code> <code>QuotaWindows</code> <code>RefreshScheduler</code> <code>StatusAggregator</code> <code>SvgPathParser</code> <code>TemplateRenderer</code> <code>UiStrings</code> <code>UpdateCheck</code> <code>WidgetHost</code> <code>WidgetTypeNames</code> <code>WidgetValueHint</code></li><li>The rest: <code>Events/Events.cs</code> (6 event records, including <code>ActionExecuted</code>), <code>Json/BeaconJson.cs</code></li></ul><h3 id="_1-7-persistence-surface-9-places-logs" tabindex="-1">1.7 Persistence surface (9 places + logs) <a class="header-anchor" href="#_1-7-persistence-surface-9-places-logs" aria-label="Permalink to &quot;1.7 Persistence surface (9 places + logs)&quot;">​</a></h3><p><code>config.json</code> <code>connections.json</code> <code>widgets.json</code> <code>pins.json</code> <code>actions.json</code> <code>notifications.json</code> (the six JSON files); <code>cache/&lt;connectionId&gt;/states.json</code> (<code>JsonCacheStore.cs:76</code>); <code>secrets.bin</code> (DPAPI, <code>DpapiSecretStore.cs:22</code>); <code>shell-state.json</code> (capsule layout, <code>ShellStateStore.cs:18</code>); logs at <code>%APPDATA%\\Beacon\\logs\\beacon-YYYYMMDD.log</code>.</p><hr><h2 id="_2-state-model-field-characterization-business-state-display-fields-local-preferences-metadata" tabindex="-1">2. State model field characterization (business state / display fields / local preferences / metadata) <a class="header-anchor" href="#_2-state-model-field-characterization-business-state-display-fields-local-preferences-metadata" aria-label="Permalink to &quot;2. State model field characterization (business state / display fields / local preferences / metadata)&quot;">​</a></h2><h3 id="_2-1-widgetstate-src-beacon-core-models-widgetstate-cs-4-21" tabindex="-1">2.1 <code>WidgetState</code> (<code>src/Beacon.Core/Models/WidgetState.cs:4-21</code>) <a class="header-anchor" href="#_2-1-widgetstate-src-beacon-core-models-widgetstate-cs-4-21" aria-label="Permalink to &quot;2.1 `WidgetState` (`src/Beacon.Core/Models/WidgetState.cs:4-21`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Characterization</th><th>Notes</th></tr></thead><tbody><tr><td><code>WidgetId</code> <code>WidgetType</code> <code>ConnectionId</code></td><td>Identifier</td><td>Stable keys, not state</td></tr><tr><td><code>Severity</code> <code>Lifecycle</code></td><td><strong>Business state</strong></td><td>Normalized projection of external-system facts</td></tr><tr><td><code>Progress</code></td><td><strong>Business state</strong></td><td>0..1 normalized progress</td></tr><tr><td><code>Payload</code></td><td><strong>Business data</strong></td><td>Feeds Action template variables (run_id etc.)</td></tr><tr><td><code>Summary</code></td><td><strong>Display field</strong></td><td>Already-localized copy mixed into the business state object (the split point called out in the design draft&#39;s §Implementation Suggestions)</td></tr><tr><td><code>DetailUrl</code></td><td>Business metadata</td><td>External detail link, consumed by the Open action</td></tr><tr><td><code>FetchedAt</code></td><td>Metadata</td><td>Freshness; <strong>participates in content equality</strong> (<code>:36</code>, counter-evidence in verification table B09)</td></tr><tr><td><code>IsStale</code> <code>ConnectionHealthy</code></td><td><strong>Derived state</strong></td><td>Inferred from failure / offline, not external facts</td></tr></tbody></table><h3 id="_2-2-config-fields-appconfig-cs-widgetconfig-cs" tabindex="-1">2.2 Config fields (<code>AppConfig.cs</code> / <code>WidgetConfig.cs</code>) <a class="header-anchor" href="#_2-2-config-fields-appconfig-cs-widgetconfig-cs" aria-label="Permalink to &quot;2.2 Config fields (`AppConfig.cs` / `WidgetConfig.cs`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Category</th><th>Fields</th></tr></thead><tbody><tr><td><strong>Local preferences (Preference)</strong></td><td><code>Theme</code> <code>UiOpacity</code> <code>Appearance.*</code> (SeverityColors / Motion.Mode / Motion.Intensity / ProgressStyle) <code>Language</code> <code>EdgeCollapseEnabled</code> <code>NumericFloatingEnabled</code> <code>PinDisplayMode</code> <code>ShowCapsule</code> <code>SettingsSidebarWidth</code> <code>SettingsWindowWidth/Height</code>; <code>WidgetConfig.Pinned</code> <code>PinLayout</code> <code>ColorOverride</code></td></tr><tr><td>Global settings (user intent)</td><td><code>Hotkey</code> <code>LaunchOnStartup</code> <code>PollIntervalSeconds</code> <code>NotificationRules</code></td></tr><tr><td>Business config</td><td><code>WidgetConfig.Config</code> (Provider parameters), all of <code>ConnectionConfig</code></td></tr><tr><td>Scheduling config</td><td><code>WidgetConfig.RefreshTier</code> <code>RefreshIntervalSeconds</code></td></tr></tbody></table><p><strong>Conclusion</strong>: <code>Summary</code> is the only display field inside the business state object; local preferences are already stored in separate files from business config (<code>config.json</code> vs <code>connections.json</code>/<code>widgets.json</code>), so the current isolation is good. Phase 1 only needs to sort out the conventions for <code>Summary</code> and the derived fields; the config file structure needs no change.</p><hr><h2 id="_3-target-model-mapping-table-current-implementation-→-new-architecture-slots" tabindex="-1">3. Target model mapping table (current implementation → new architecture slots) <a class="header-anchor" href="#_3-target-model-mapping-table-current-implementation-→-new-architecture-slots" aria-label="Permalink to &quot;3. Target model mapping table (current implementation → new architecture slots)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Current implementation</th><th>New architecture slot (design draft §10)</th><th>Migration action</th></tr></thead><tbody><tr><td><code>IConnectionProvider</code> / <code>IWidgetProvider</code> (<code>IConnectionProvider.cs:12,29</code>)</td><td>Data Acquisition: Connection / Widget Providers</td><td><strong>Keep as-is</strong></td></tr><tr><td><code>RefreshScheduler</code> (<code>RefreshScheduler.cs:17</code>)</td><td>Data Acquisition: Refresh Scheduler</td><td>Keep; the <code>Kick</code> semantics is exactly 「Action 后定向刷新」 (targeted refresh after an Action); no new mechanism needed</td></tr><tr><td><code>ICacheStore</code> / <code>JsonCacheStore</code></td><td>Data Acquisition: Cache</td><td>Keep</td></tr><tr><td><code>ISecretStore</code> / <code>DpapiSecretStore</code></td><td>Security: Secret Store</td><td>Keep</td></tr><tr><td><code>WidgetHost</code> (<code>WidgetHost.cs:12</code>)</td><td>Data Acquisition lifecycle + state publishing</td><td><strong>Split candidate</strong>: keep data fetching / lifecycle; the 「统一状态入口」 (unified state entry) responsibility yields to the State Store (Phase 1)</td></tr><tr><td><code>EventBus</code> + <code>Events.cs</code> (<code>IEventBus.cs:4</code>)</td><td>Reactive Core: Event Stream</td><td>Keep</td></tr><tr><td><code>StatusAggregator</code> (<code>StatusAggregator.cs:11</code>)</td><td>Reactive Core: Derived State / Aggregation</td><td>Keep; the snapshot semantics can merge into the State Store or stay independent</td></tr><tr><td><code>WidgetState.Equals</code> (<code>WidgetState.cs:24-58</code>)</td><td>Reactive Core: Change Detection</td><td><strong>Modification point</strong>: remove <code>FetchedAt</code> from content equality (see §4 Phase 1)</td></tr><tr><td><code>NotificationEngine</code> (<code>NotificationEngine.cs:14</code>)</td><td>Signal &amp; Notification</td><td>Keep</td></tr><tr><td><code>ActionRunner</code> + 7 executors (<code>ActionRunner.cs:15</code>)</td><td>Command &amp; Action: Dispatcher / Executor</td><td>Keep; moving <code>ActionResult</code> to five states is a contract change, pending decision</td></tr><tr><td><code>WidgetTypeDescriptor</code> (<code>WidgetTypeDescriptor.cs:15</code>)</td><td>Display Composition: Component Contracts</td><td><strong>Evolution point</strong>: evolve from 「设置表单元数据 + L0 准入」 (settings-form metadata + L0 admission) into display-component capability declarations (the forerunner of the Phase 3 Component Descriptor)</td></tr><tr><td><code>MakeStateRow</code> (<code>QuickPanelWindow.cs:471</code>)</td><td>Display Composition: display components</td><td><strong>Replacement point</strong>: generic row rendering → first batch of the component library (Phase 2)</td></tr><tr><td>The six Windows (§1.5)</td><td>Windows UI: Pinned Tiles / Floating / Quick Panel / Detail / Settings</td><td>Keep; only the rendering segment adopts the component library</td></tr><tr><td><code>UiPalette</code> <code>ThemeColors</code> <code>MotionEngine</code> <code>DpiLayoutMath</code> <code>ContrastMath</code> <code>HighContrastPalette</code></td><td>Design System: design tokens</td><td><strong>Consolidation point</strong>: scattered constants → unified token system (Phase 2)</td></tr><tr><td><code>QuotaWindows</code> <code>WidgetValueHint</code> <code>QuickPanelSections</code> <code>QuickPanelFilter</code></td><td>Reactive Core: Selectors</td><td><strong>Consolidation point</strong>: ready-made material for the first batch of Selectors (Phase 1)</td></tr><tr><td>— (no corresponding implementation)</td><td>State Store / Binding Engine / Component Registry / HTML Renderer Host</td><td><strong>New build</strong> (Phase 1-4)</td></tr></tbody></table><hr><h2 id="_4-gap-and-migration-plan-by-phase" tabindex="-1">4. Gap and migration plan (by phase) <a class="header-anchor" href="#_4-gap-and-migration-plan-by-phase" aria-label="Permalink to &quot;4. Gap and migration plan (by phase)&quot;">​</a></h2><h3 id="phase-1-reactive-state-and-data-flow" tabindex="-1">Phase 1 Reactive state and data flow <a class="header-anchor" href="#phase-1-reactive-state-and-data-flow" aria-label="Permalink to &quot;Phase 1 Reactive state and data flow&quot;">​</a></h3><ol><li>Introduce <code>IStateStore</code> (in-process implementation): snapshot reads + subscription + content-level change detection. After a successful refresh <code>WidgetHost</code> writes into the Store instead, and the Store publishes <code>WidgetStateChanged</code> when it detects a change — <strong>the publish point moves from WidgetHost to the Store</strong>; the event contract is unchanged and the UI notices nothing.</li><li>Change detection rule: remove <code>FetchedAt</code> from <code>WidgetState</code> content equality (or add <code>ContentVersion</code>) so that 「仅刷新时间变化」 (a refresh-time-only change) no longer triggers downstream.</li><li>Selector consolidation: <code>QuotaWindows</code> / <code>WidgetValueHint</code> / <code>QuickPanelSections</code> / <code>QuickPanelFilter</code> are relocated into the Selector layer; signatures unchanged, only the namespace and documentation positioning move.</li><li><strong>Regression surface</strong>: after dedup the UI no longer rebuilds every tick — scenarios S (event stream), O (panel counts), Q (capsule counts) must all stay green; F5 (offline degradation produces exactly 1 notification) depends on stale events not being swallowed by dedup, so unit tests come first.</li><li>Rollback: the Store is introduced as a bypass (revertible as a whole in one commit) and is not merged into the WidgetHost rewrite.</li></ol><h3 id="phase-2-design-system-and-base-component-library" tabindex="-1">Phase 2 Design system and base component library <a class="header-anchor" href="#phase-2-design-system-and-base-component-library" aria-label="Permalink to &quot;Phase 2 Design system and base component library&quot;">​</a></h3><ol><li>Tokenization: <code>UiPalette</code> / <code>ThemeColors</code> / <code>MotionEngine</code> / <code>DpiLayoutMath</code> are consolidated into a token layer; <strong>color values must not change</strong> (the G-series CI pixel assertions pin the current color values; changing a value turns them red).</li><li>The first batch of components is reverse-engineered from <code>MakeStateRow</code>: Metric, Status Indicator, Progress, Key-Value, Status Card, List, Action Button, Link, Stack, Grid, Section, Conditional, Empty, Loading, Error, Offline.</li><li>The visual example page becomes its own window (debug builds only), not part of the product window set.</li></ol><h3 id="phase-3-component-composition-and-data-binding" tabindex="-1">Phase 3 Component composition and data binding <a class="header-anchor" href="#phase-3-component-composition-and-data-binding" aria-label="Permalink to &quot;Phase 3 Component composition and data binding&quot;">​</a></h3><ol><li><code>Component Descriptor</code>: add display declarations on top of <code>WidgetTypeDescriptor</code> (component type + bindings + density), <strong>without overturning the existing 23 type keys</strong>.</li><li><code>WidgetConfig</code> gains incremental optional fields (<code>ConfigVersion</code> increments, old files stay readable) — the compatibility plan is in §5.</li><li>Selector-to-component-property binding + multi-source composition (the current single-<code>ConnectionId</code> nature of <code>WidgetState</code> is not broken; composition happens at the component layer aggregating multiple WidgetIds).</li></ol><h3 id="phase-4-html-small-screens" tabindex="-1">Phase 4 HTML small screens <a class="header-anchor" href="#phase-4-html-small-screens" aria-label="Permalink to &quot;Phase 4 HTML small screens&quot;">​</a></h3><p><strong>Precondition decision</strong>: the boundary ruling against <code>docs/master-plan.md:769</code> 「不引入 WebView 或其他 UI 框架来重复实现桌面外壳」 — does HTML enter only the 「数据显示小屏幕」 (data-display small screens) and not the 「外壳」 (shell), or does everything stay native? No work starts before the ruling.</p><h3 id="phase-5-6" tabindex="-1">Phase 5 / 6 <a class="header-anchor" href="#phase-5-6" aria-label="Permalink to &quot;Phase 5 / 6&quot;">​</a></h3><p>Component catalog expansion and full regression; the 71-item on-machine checklist (<code>docs/acceptance-checklist.md</code>) remains the acceptance base, re-run item by item in Phase 6.</p><hr><h2 id="_5-compatibility-plan-proposal-pending-decision" tabindex="-1">5. Compatibility plan (proposal, pending decision) <a class="header-anchor" href="#_5-compatibility-plan-proposal-pending-decision" aria-label="Permalink to &quot;5. Compatibility plan (proposal, pending decision)&quot;">​</a></h2><ol><li>The six JSON file names and existing field semantics are <strong>entirely unchanged</strong> (continuing the implemented convention recorded in verification table G02).</li><li>The new component model enters as incremental optional fields on <code>WidgetConfig</code>; <code>ConfigVersion</code> increments but old versions stay readable; no migration, no renaming.</li><li>The existing 23 type keys, 7 Action Type strings, and all window layers are preserved; componentization only replaces the rendering segment and the state entry point, leaving Providers and executors untouched.</li><li>On-machine acceptance capability is retained: the 71-item on-machine checklist and the CI visual-evidence scenarios remain in force; the phase counts as complete only after the full Phase 6 regression.</li></ol><h2 id="_6-pending-decision-list-2026-10-16-patrol1016-decided-1234-on-the-user-s-behalf-only-item-3-remains-open" tabindex="-1">6. Pending-decision list (2026-10-16 PATROL1016 decided ①②③④ on the user&#39;s behalf; only item 3 remains open) <a class="header-anchor" href="#_6-pending-decision-list-2026-10-16-patrol1016-decided-1234-on-the-user-s-behalf-only-item-3-remains-open" aria-label="Permalink to &quot;6. Pending-decision list (2026-10-16 PATROL1016 decided ①②③④ on the user&#39;s behalf; only item 3 remains open)&quot;">​</a></h2><ol><li><s><strong>Contract freeze scope</strong></s> → 已代决①③: the <code>IStateStore</code> contract is frozen = the landed signature; the <code>ActionResult</code> target five states land in Phase 5 (契约.md §4).</li><li><s><strong>Remove <code>FetchedAt</code> from content equality</strong></s> → 已代决②: dedup is enabled by default since <code>d71bdc8</code>, rollback switch kept (契约.md §4).</li><li><strong>The boundary between HTML small screens and master-plan:769</strong>: does the data-display surface allow HTML while the shell stays native, or does everything stay native? <strong>Out of scope, still pending user ruling (before Phase 4 starts).</strong></li><li><s><strong>Whether the four items of the §5 compatibility plan</strong> are frozen as-is</s> → 已代决④: frozen as-is (契约.md §3).</li></ol>',47)])])}const u=t(i,[["render",c]]);export{p as __pageData,u as default};
